for x in L:lines.append(f"| {x['role']} | {x['run']} | {x['cpu_mean_pct']:.2f}% | {x['cpu_peak_pct']:.2f}% | {x['iowait_mean_pct']:.5f}% | {x['swapin_pages']}/{x['swapout_pages']} |")
